package ru.neverland.townyquests.cooperative;
import java.util.*;
import org.bukkit.configuration.file.YamlConfiguration;
public final class CooperativeTemplatesSmoke {
    static int checks;static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}static void rejects(Runnable action,String why){try{action.run();throw new AssertionError(why);}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{var y=new YamlConfiguration();try(var input=CooperativeTemplatesSmoke.class.getResourceAsStream("/cooperative.yml")){y.load(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8));}var root=y.getConfigurationSection("templates");check(y.getBoolean("enabled")&&root.getKeys(false).size()==2,"optional defaults contain two explicit templates");for(String id:root.getKeys(false)){var row=root.getConfigurationSection(id);var needs=new HashMap<String,Long>();var materials=row.getConfigurationSection("materials");for(String material:materials.getKeys(false))needs.put(material,materials.getLong(material));var template=new CooperativeService.Template(id,row.getString("title"),row.getString("scope"),row.getString("unlock"),row.getLong("minimum-city-credit"),needs);needs.clear();check(!template.needs().isEmpty(),"budget copy is immutable");check((template.id()+"_"+UUID.randomUUID().toString().replace("-","")).length()<=48,"city-scoped id fits durable ledger");}
        rejects(()->new CooperativeService.Template("test","Test","CITY","legacy_unlock",1,Map.of("STONE",1L)),"optional unlock cannot collide with old chain namespace");rejects(()->new CooperativeService.Template("too_long_identifier","Test","CITY","joint_ok",1,Map.of("STONE",1L)),"oversize city id rejected before SQL");rejects(()->new CooperativeService.Template("test","Test","SERVER","joint_ok",11,Map.of("STONE",10L)),"impossible contributor threshold rejected");rejects(()->new CooperativeService.Template("test","Test","SERVER","joint_ok",1,Map.of("STONE",-1L)),"negative material quantity rejected");rejects(()->new CooperativeService.Template("test","Test","SERVER","joint_ok",1,Map.of("UNKNOWN_MATERIAL",1L)),"bad Bukkit material rejected");rejects(()->new CooperativeService.Template("test","Test","SERVER","joint_ok",1,Map.of("AIR",1L)),"air cannot fund a construction budget");System.out.println("CooperativeTemplatesSmoke PASS: "+checks+" checks; bundled templates, immutable budgets, identifier limits, isolated unlock namespace and material validation");}
}
